case 'Approve_Flow':

var xRow = result[0].Value
var xValue = result[1].Value
var iHtml = g._getColumnOrder('html_duyet');

var o = null;
o = g._getItem(xRow, iHtml);
var p = o.parentElement;
if (p.children.length == 3){
p.removeChild(p.children[2])
}

o.style.display = 'none';
var dv = document.createElement('div');
o.parentElement.append(dv);
dv.outerHTML = "&lt;div id='div_html_duyet_item_" + xRow + "' class='div_html_duyet' style='display: none'&gt;" + xValue + "&lt;/div&gt;";

viewHtmlDuyetDetail(xRow, e)
var dvi = $get('img_html_' + xRow);
dvi._id = xRow
dvi.onmouseleave = function(e){
hideHtmlDuyetDetail(xRow, e)
}
break;

