}

.div_html_duyet td {
border-right: solid 1px #ccc;
border-bottom: solid 1px #ccc;
}

.div_html_duyet td div{
min-width: 100px;
padding: 5px 10px;
}

.div_html_duyet td div:hover{
color: red;
}

.td_duyet_noborder{
